<?php if($comm): ?>
<section class="comm-card"><h2>Credit payment requests</h2><div class="comm-scroll"><table class="comm-table"><thead><tr><th>Request / transfer reference</th><th>Total / credits</th><th>Status</th><th>Payment</th></tr></thead><tbody><?php foreach($comm['requests'] as $r):if($r['module_key']!==$channel)continue;$legacySubscription=$r['purpose']==='subscription' && in_array($channel,array('sms','email'),true); ?><tr><td>#<?= (int)$r['id']; ?> · <?= $h($r['purpose']); ?><?php if($r['purpose']==='recharge'): ?><br><strong><?= $h('MP-COMM-'.str_pad((string)$r['id'],6,'0',STR_PAD_LEFT)); ?></strong><br><span class="muted">Use this as your bank transfer narration.</span><?php endif; ?><br><span class="muted"><?= $h($r['billing_period']??'Credits'); ?><?php if(!empty($r['automation_plan_key'])): ?> · <?= $h($comm['automation']['plans'][$r['automation_plan_key']]['name']??$r['automation_plan_key']); ?><?php endif; ?></span></td><td><?= $money($r['total_kobo']??$r['amount_kobo']); ?><?php if(!empty($r['tax_kobo'])): ?><br><span class="muted">Net <?= $money($r['net_kobo']??$r['amount_kobo']); ?> · VAT <?= $money($r['tax_kobo']); ?></span><?php endif; ?><?= $r['credit_units']?' / '.number_format($r['credit_units']).' credits':''; ?></td><td><span class="comm-badge <?= $r['status']==='approved'?'ok':'off'; ?>"><?= $h(str_replace('_',' ',$r['status'])); ?></span></td><td><?php if($legacySubscription): ?><span class="notice error">This is an older plan request. SMS/Email access is now included. Contact your account administrator about any payment already made.</span><?php elseif($r['payment_reference']): ?><span class="mini"><?= $h($r['payment_reference']); ?></span><?php if($r['status']==='awaiting_payment'): ?><span class="muted">Payment confirmation is automatic. Do not pay again; credits will appear when confirmed.</span><?php endif; ?><?php else: ?>Sales will contact you<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>

<?php endif; ?>

<?php $receiptDocs=array_filter($comm['review']['documents']??array(),function($d){return $d['kind']==='receipt';});if($receiptDocs): ?><section class="comm-card"><h2>Your uploaded receipts</h2><?php foreach($receiptDocs as $doc): ?><p>Request #<?= (int)$doc['reference_id']; ?> · <a href="<?= base_url('communications/document/'.(int)$doc['id']); ?>"><?= $h($doc['filename']); ?></a></p><?php endforeach; ?></section><?php endif; ?>
